def _creation_parent(config: dict[str, Any]) -> dict[str, Any] | None:
    origin = config.get("mona_native_research") or {}
    identifier = origin.get("strategy_id")
    if identifier is None:
        return None
    detail = strategy_detail(identifier)
    if detail["source"] != "custom":
        raise HTTPException(422, "内置策略只读，不能通过AI修改；请选择自定义策略。")
    if detail.get("deleted"):
        raise HTTPException(409, "This strategy was deleted and cannot be modified")
    if origin.get("strategy_version") != detail["version"]:
        raise HTTPException(409, "自定义策略版本已更新，请重新打开后再修改。")
    return detail


